from pathlib import Path
import base64, zlib, subprocess, tempfile

PATCH_B64 = ''
TEST_B64 = ''

root=Path(__file__).resolve().parents[2]
patch=zlib.decompress(base64.b64decode(PATCH_B64))
test=zlib.decompress(base64.b64decode(TEST_B64))
with tempfile.NamedTemporaryFile(delete=False,suffix='.patch') as handle:
    handle.write(patch)
    patch_path=handle.name
subprocess.run(['git','apply',patch_path],cwd=root,check=True)
test_path=root/'working_source'/'tests'/'regression_post_v95_new_packet_ocr.py'
test_path.write_bytes(test)
print('Applied post-v95 new-packet parser fixes and regression.')
